    "daily_nudge.notify.send_key_env": ["SendKey 的环境变量名","SendKey variable name","Nom de variable du SendKey","Имя переменной SendKey","Nombre de variable de SendKey","SendKey の環境変数名","Nome da variável da SendKey","Variablenname für SendKey","Назив променљиве за SendKey","SendKey 환경 변수 이름"],
    "daily_nudge.notify.host": ["SMTP 服务器","SMTP server","Serveur SMTP","Сервер SMTP","Servidor SMTP","SMTP サーバー","Servidor SMTP","SMTP-Server","SMTP сервер","SMTP 서버"],
